-- 3. XÓA BỎ DỮ LIỆU BỊ HỎNG ENCODING TRONG BLOG VÀ HỎI ĐÁP
DELETE FROM answer WHERE content LIKE '%?%';
DELETE FROM question WHERE title LIKE '%?%';
DELETE FROM blog_post WHERE title LIKE '%?%';

-- 4. THÊM DANH SÁCH BẤT ĐỘNG SẢN VÀ BÀI ĐĂNG PHÒNG TRỌ ĐA DẠNG
ON DUPLICATE KEY UPDATE name = VALUES(name), price = VALUES(price), description = VALUES(description);

ON DUPLICATE KEY UPDATE title = VALUES(title), status = VALUES(status);

-- Chuẩn hóa tên và trạng thái cho các bài đăng và bất động sản cũ (4..12) để đồng bộ ACTIVE và sạch tiếng Việt
UPDATE property SET name = 'Căn hộ Studio Full Nội Thất Làng Đại Học Thủ Đức' WHERE id IN (4, 5, 9);
