UPDATE property SET name = 'Phòng Trọ Gác Cao Ngõ 27 Tạ Quang Bửu' WHERE id IN (8, 12);

UPDATE listing SET title = '[VIP KIM CƯƠNG] Studio Full Đồ Ban Công Thoáng Sát ĐHQG TP.HCM', status = 'ACTIVE' WHERE id IN (4, 8);
UPDATE listing SET title = '[VIP VÀNG] Phòng trọ khép kín Hòa Lạc gần ĐH FPT & ĐHQG', status = 'ACTIVE' WHERE id IN (5, 9);
