ON DUPLICATE KEY UPDATE content = VALUES(content);

-- 10. THÊM 15 HỘI THOẠI CHAT ĐA DẠNG
ON DUPLICATE KEY UPDATE context_title = VALUES(context_title), context_image = VALUES(context_image);

-- Cài đặt Muted và Hidden cho User 4 để test chức năng
ON DUPLICATE KEY UPDATE is_muted = VALUES(is_muted), is_hidden = VALUES(is_hidden);

-- 11. THÊM DANH SÁCH TIN NHẮN THỰC TẾ (>120 TIN NHẮN, CÓ CONVERSATION >60 TIN ĐỂ TEST PHÂN TRANG)
ON DUPLICATE KEY UPDATE content = VALUES(content), is_recalled = VALUES(is_recalled);

-- 12. THÊM 35 THÔNG BÁO HỆ THỐNG & TIN NHẮN (>=30 NOTIFICATIONS)
ON DUPLICATE KEY UPDATE message = VALUES(message);

-- 13. CẬP NHẬT VÀ THÊM QUẢNG CÁO BANNER TIẾNG VIỆT CHUẨN (>=8 ADS TỔNG CỘNG)
ON DUPLICATE KEY UPDATE title = VALUES(title), placement = VALUES(placement), banner_image = VALUES(banner_image), destination_url = VALUES(destination_url), status = VALUES(status);

-- 14. THÊM DỮ LIỆU THỐNG KÊ ANALYTICS THỰC TẾ (>=300 SỰ KIỆN)
