(61, 86, 'Bộ nồi chảo inox 3 đáy Fivestar dùng mọi loại bếp', 'Đồ gia dụng', 270000, 'Inox 430 bắt từ cực nhạy', 'Hà Nội', 'Thạch Thất', 'Gồm 1 nồi nhỡ 20cm, 1 quánh 16cm và 1 chảo chống dính 24cm.', 'https://images.unsplash.com/photo-1584990347449-399c6802e864?w=500', 'ACTIVE', NOW())
INSERT INTO service_listing (id, provider_id, category, title, description, price_from, province, district, phone, image_url, status, created_at) VALUES
(30, 3, 'Chuyển trọ', 'Chuyển Phòng Trọ Sinh Viên Trọn Gói Giá Rẻ', 'Xe ba gác và xe tải nhỏ hỗ trợ bê vác đồ đạc lên tầng, đảm bảo an toàn không trầy xước.', 250000, 'Hà Nội', 'Cầu Giấy', '0912345678', 'https://images.unsplash.com/photo-1600518464441-9154a4dea21b?w=600', 'ACTIVE', NOW()),
(31, 13, 'Giặt ủi', 'Giặt Sấy Lấy Ngay Siêu Tốc Trong 2 Giờ', 'Giặt riêng từng máy, nước giặt xả Comfort thơm tho, gấp đồ gọn gàng, giao nhận tận nơi.', 25000, 'Hà Nội', 'Đống Đa', '0987654321', 'https://images.unsplash.com/photo-1517677208171-0bc6725a3e60?w=600', 'ACTIVE', NOW()),
(32, 14, 'Sửa chữa', 'Sửa Chữa Điện Nước & Lắp Đặt Thiết Bị Phòng Trọ', 'Xử lý rò rỉ ống nước, chập điện, thay vòi sen, lắp quạt trần, sửa bình nóng lạnh tại nhà.', 80000, 'Hà Nội', 'Thanh Xuân', '0901234567', 'https://images.unsplash.com/photo-1581578731548-c64695cc6952?w=600', 'ACTIVE', NOW()),
(33, 3, 'Dọn vệ sinh', 'Vệ Sinh Dọn Dẹp Phòng Trọ Chuyên Nghiệp Khi Trả Phòng', 'Tẩy cặn nhà tắm, chà sàn, lau kính, quét mạng nhện, trả phòng sạch sẽ nhận lại 100% tiền cọc.', 180000, 'Hà Nội', 'Cầu Giấy', '0912345678', 'https://images.unsplash.com/photo-1584820927498-cfe5211fd8bf?w=600', 'ACTIVE', NOW()),
(34, 13, 'Sửa chữa', 'Vệ Sinh Bảo Dưỡng Điều Hòa Máy Lạnh Sinh Viên', 'Xịt rửa dàn nóng dàn lạnh, bơm gas bổ sung, kiểm tra rò điện, máy chạy êm mát sâu.', 120000, 'Hà Nội', 'Hai Bà Trưng', '0987654321', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=600', 'ACTIVE', NOW()),
(35, 3, 'Internet', 'Gia Hạn Lắp Đặt Mạng Internet Wifi Cáp Quang Phòng Trọ', 'Kéo dây mạng CAT6, cài đặt cục phát wifi băng tần kép tốc độ cao, hỗ trợ kỹ thuật 24/7.', 150000, 'Hà Nội', 'Nam Từ Liêm', '0934567890', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=600', 'ACTIVE', NOW()),
(36, 14, 'Khóa cửa', 'Cắt Khóa Làm Lại Chìa Khóa Cổng Khóa Vân Tay', 'Mở khóa cửa khi quên chìa, sao chép thẻ từ thang máy, đánh thêm chìa khóa phòng an toàn.', 50000, 'Hà Nội', 'Cầu Giấy', '0901234567', 'https://images.unsplash.com/photo-1582139329536-e7284fece509?w=600', 'ACTIVE', NOW()),
(37, 3, 'Gia sư', 'Gia Sư & Luyện Thi Đại Học Toán - Lý - Hóa - Tiếng Anh', 'Đội ngũ sinh viên Bách Khoa, Ngoại Thương dạy kèm tận tâm, nắm chắc phương pháp.', 120000, 'Hà Nội', 'Đống Đa', '0978901234', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=600', 'ACTIVE', NOW()),
(38, 13, 'Ăn uống', 'Cơm Tháng Sinh Viên Chuẩn Vị Mẹ Nấu Giao Tận Cửa', 'Thực đơn thay đổi mỗi ngày, nguyên liệu sạch, nóng hổi, miễn phí ship trong bán kính 2km.', 30000, 'Hà Nội', 'Thạch Thất', '0965432109', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=600', 'ACTIVE', NOW()),
(39, 14, 'Xe máy', 'Bảo Dưỡng Thay Nhớt Xe Máy Lưu Động', 'Thay nhớt Motul, Castrol chính hãng, tăng xích, bơm lốp, kiểm tra phanh miễn phí tại nhà.', 85000, 'Hà Nội', 'Hà Đông', '0901234567', 'https://images.unsplash.com/photo-1486006920555-c77dce18193b?w=600', 'ACTIVE', NOW())
INSERT INTO blog_post (id, author_id, category, title, summary, content, cover_image, tags, status, reading_minutes, published_at, updated_at) VALUES
(100, 1, 'GUIDE', 'Cẩm nang kiểm tra an toàn PCCC khi thuê trọ sinh viên', 'Những tiêu chí quan trọng về lối thoát hiểm, thiết bị cứu hỏa và hệ thống điện sinh viên cần kiểm tra kỹ trước khi ký hợp đồng.', 'Phòng cháy chữa cháy (PCCC) là ưu tiên số một khi chọn nơi ở trọ. Sinh viên nên lưu ý: 1. Có ít nhất 2 lối thoát nạn độc lập (cửa chính và thang thoát hiểm hoặc ban công mở). 2. Bình chữa cháy bột hoặc khí CO2 còn hạn sử dụng, đặt nơi dễ thấy. 3. Hệ thống dây dẫn điện đi trong ống gen bảo vệ, có aptomat ngắt tự động chống chập cháy. 4. Khu vực sạc xe máy điện có vách ngăn chống cháy lan. Đừng vì ham rẻ mà bỏ qua những rủi ro đe dọa trực tiếp đến tính mạng bản thân.', 'https://images.unsplash.com/photo-1541976590-713941681591?w=800', 'pccc,an toàn,thuê trọ', 'PUBLISHED', 5, NOW(), NOW()),
(101, 1, 'EXPERIENCE', 'Kinh nghiệm chọn phòng trọ phù hợp cho tân sinh viên', 'Hướng dẫn chi tiết từ khảo sát vị trí, ngân sách, ánh sáng đến an ninh khu vực xung quanh trường đại học.', 'Bước vào giảng đường đại học, chọn phòng trọ là thử thách tự lập đầu tiên: 1. Khảo sát bán kính di chuyển: Tốt nhất cách trường dưới 3km hoặc thuận tiện tuyến xe bus. 2. Kiểm tra nguồn nước sinh hoạt: Nước máy trong veo, không có mùi tanh hay váng phèn. 3. Quan sát môi trường xung quanh: Khu dân trí, đèn đường ban đêm, gần chợ và trạm y tế. 4. Đi xem phòng vào cả buổi trưa (đo độ nóng) và buổi tối (đo độ ồn ào).', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800', 'kinh nghiệm,tân sinh viên,phòng trọ', 'PUBLISHED', 6, NOW(), NOW()),
(102, 1, 'LEGAL', 'Những điều cần kiểm tra trước khi đặt cọc phòng trọ', 'Tránh mất tiền oan với các điều khoản giấy cọc, bằng chứng bàn giao và xác minh quyền sở hữu của chủ nhà.', 'Không ít bạn sinh viên bị lừa tiền cọc vì vội vàng. Checklist bảo vệ bạn: 1. Yêu cầu xem căn cước công dân và sổ đỏ hoặc hợp đồng ủy quyền của chủ nhà. 2. Giấy biên nhận đặt cọc phải ghi rõ số tiền, thời hạn giữ phòng, ngày bắt đầu tính tiền thuê và điều kiện hoàn cọc 100% nếu chủ trọ vi phạm. 3. Thỏa thuận chi tiết giá điện, nước, internet, phí dịch vụ ngay trong giấy cọc, tránh trường hợp tăng giá bất ngờ khi dọn đến.', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?w=800', 'đặt cọc,pháp lý,hợp đồng', 'PUBLISHED', 4, NOW(), NOW()),
(103, 1, 'ROOMMATE', 'Mẹo chia tiền điện nước khi ở ghép không mất lòng', 'Xây dựng quy tắc minh bạch, công bằng về chi phí sinh hoạt để tình bạn cùng phòng luôn bền vững.', 'Ở ghép giúp tiết kiệm chi phí nhưng dễ nảy sinh bất hòa vì tiền bạc: 1. Dùng app ghi chép chi tiêu chung như Splitwise hoặc sổ quỹ chung. 2. Tiền phòng chia đều; tiền điện nước nếu có bạn dùng máy tính gaming hoặc điều hòa nhiều hơn nên thỏa thuận tỷ lệ 60-40 hợp lý. 3. Các chi phí gia vị, nước mắm, dầu ăn, nước rửa bát gom thành quỹ nhỏ đầu tháng 50.000đ/người. Minh bạch ngay từ đầu là chìa khóa của sự hòa thuận.', 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800', 'ở ghép,chi phí,điện nước', 'PUBLISHED', 4, NOW(), NOW()),
(104, 1, 'SECURITY', 'Các dấu hiệu nhận biết tin cho thuê phòng lừa đảo', 'Cảnh giác với các thủ đoạn giả mạo chủ trọ, ép chuyển khoản giữ chỗ và chiêu trò phòng giá rẻ bất thường.', 'Cảnh báo 5 chiêu trò lừa đảo phổ biến: 1. Phòng view đẹp như khách sạn 5 sao nhưng giá chỉ 1.5 triệu (hình ảnh ăn cắp trên mạng). 2. Chủ nhà báo đang đi công tác xa, yêu cầu chuyển cọc giữ chỗ gấp qua số tài khoản ảo. 3. Địa chỉ ma hoặc hẹn ra quán cafe thay vì xem phòng trực tiếp. 4. Bắt đóng phí xem phòng 50.000đ - 100.000đ. Nhớ nguyên tắc vàng: Không chuyển tiền khi chưa trực tiếp xem phòng và gặp chủ trọ.', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=800', 'lừa đảo,cảnh giác,an ninh', 'PUBLISHED', 5, NOW(), NOW()),
(105, 1, 'MOVING', 'Checklist chuyển trọ nhanh gọn dành cho sinh viên', 'Các bước đóng gói đồ đạc khoa học, dọn dẹp bàn giao và tiết kiệm chi phí xe chuyển nhà.', 'Chuyển nhà không còn là nỗi ám ảnh nếu bạn áp dụng checklist: 1. Thanh lý hoặc cho bớt đồ dùng không còn sử dụng trước 1 tuần. 2. Phân loại đồ theo thùng carton: Quần áo, sách vở, đồ điện tử, đồ dễ vỡ dán nhãn rõ ràng. 3. Chụp ảnh hiện trạng phòng cũ trước khi bàn giao để đối chiếu trừ cọc công bằng. 4. Đặt xe chuyển trọ sinh viên trên UniHome để được giá ưu đãi tốt nhất.', 'https://images.unsplash.com/photo-1600518464441-9154a4dea21b?w=800', 'chuyển nhà,tiết kiệm,checklist', 'PUBLISHED', 5, NOW(), NOW()),
(106, 1, 'LEGAL', 'Thủ tục đăng ký tạm trú trực tuyến qua Cổng Dịch Vụ Công & VNeID', 'Hướng dẫn từng bước khai báo tạm trú online chuẩn quy định, tránh bị phạt hành chính.', 'Theo Luật Cư trú, sinh viên thuê trọ phải đăng ký tạm trú trong vòng 30 ngày: 1. Tải ứng dụng VNeID kích hoạt định danh mức 2 hoặc truy cập dichvucong.bocongan.gov.vn. 2. Chọn mục Đăng ký tạm trú, điền thông tin địa chỉ nhà trọ và đính kèm ảnh hợp đồng thuê nhà. 3. Nộp hồ sơ và theo dõi tiến độ giải quyết trực tuyến. Thủ tục hoàn toàn miễn phí và không cần mất công ra trụ sở công an phường.', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800', 'tạm trú,vneid,dịch vụ công', 'PUBLISHED', 7, NOW(), NOW()),
(107, 1, 'LIFESTYLE', 'Bí quyết nấu ăn ngon bổ rẻ tại phòng trọ dưới 30k mỗi ngày', 'Cách lên thực đơn tuần, đi chợ đầu mối và bảo quản thực phẩm tươi ngon cho sinh viên.', 'Tự nấu ăn vừa đảm bảo vệ sinh vừa tiết kiệm gấp đôi so với ăn ngoài: 1. Đi chợ đầu mối vào sáng sớm mua rau củ, thịt cá tươi với giá sỉ. 2. Sơ chế, chia nhỏ từng phần thịt ướp sẵn bỏ ngăn đá tủ lạnh mini. 3. Sử dụng nồi cơm điện đa năng để vừa nấu cơm vừa hấp trứng, hấp rau. Một bữa cơm sinh viên đầy đủ chất gồm 1 món mặn, 1 món rau luộc và canh chỉ tốn khoảng 25.000đ - 30.000đ.', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800', 'nấu ăn,sinh viên,tiết kiệm', 'PUBLISHED', 5, NOW(), NOW()),
(108, 1, 'TIPS', 'Cách tiết kiệm điện điều hòa mùa nắng nóng cho phòng trọ', 'Mẹo cài đặt nhiệt độ, vệ sinh lưới lọc và chống thất thoát nhiệt giúp hóa đơn điện không bị vọt xà.', 'Tiền điện mùa hè luôn là gánh nặng lớn: 1. Cài đặt nhiệt độ từ 26 đến 28 độ C kết hợp quạt cây thoang thoảng giúp mát đều mà tiết kiệm 20% điện. 2. Vệ sinh lưới lọc bụi 2 tuần một lần để gió lưu thông tốt. 3. Bịt kín các khe cửa sổ, cửa chính tránh thất thoát khí lạnh. 4. Tắt aptomat điều hòa khi không sử dụng vì máy vẫn tiêu thụ điện ngầm ở chế độ chờ.', 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?w=800', 'tiết kiệm điện,điều hòa,mùa hè', 'PUBLISHED', 4, NOW(), NOW()),
(109, 1, 'ROOMMATE', 'Văn hóa ứng xử phòng trọ: 7 nguyên tắc vàng cần nhớ', 'Làm sao để sống chung hòa thuận, văn minh và được chủ trọ cũng như hàng xóm quý mến.', 'Không gian phòng trọ tuy nhỏ nhưng là xã hội thu nhỏ: 1. Giữ trật tự sau 23h đêm, đeo tai nghe khi nghe nhạc hoặc chơi game. 2. Không tự ý dùng đồ đạc của người khác khi chưa xin phép. 3. Dắt xe nhẹ nhàng, xếp gọn gàng trong khu để xe chung. 4. Đổ rác đúng giờ và phân loại rác thải. Tôn trọng người khác chính là tạo dựng cuộc sống bình yên cho chính mình.', 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=800', 'văn hóa,ứng xử,sống chung', 'PUBLISHED', 4, NOW(), NOW()),
(110, 1, 'GUIDE', 'Hướng dẫn kiểm tra hợp đồng thuê trọ từ A đến Z', 'Bóc tách các điều khoản cam kết, thời hạn chấm dứt hợp đồng và trách nhiệm bảo dưỡng sửa chữa thiết bị.', 'Hợp đồng thuê nhà là văn bản pháp lý cao nhất bảo vệ bạn. Hãy đọc kỹ: 1. Trách nhiệm sửa chữa bóng đèn, ống nước, máy lạnh hỏng do thời gian hay do người thuê. 2. Thời hạn báo trước khi trả phòng (thường là 30 ngày) để được hoàn đủ tiền cọc. 3. Quy định về việc tăng giá phòng và giá dịch vụ trong thời hạn hợp đồng. 4. Chữ ký xác nhận của cả hai bên trên từng trang hợp đồng.', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?w=800', 'hợp đồng,pháp lý,thuê nhà', 'PUBLISHED', 6, NOW(), NOW()),
(111, 1, 'SECURITY', 'Kinh nghiệm bảo vệ tài sản cá nhân tại khu nhà trọ', 'Chống trộm cắp máy tính, xe máy và tư trang cá nhân hiệu quả ở các xóm trọ đông người.', 'Tài sản sinh viên như laptop, xe máy rất dễ lọt vào tầm ngắm của kẻ gian: 1. Trang bị khóa chữ U hoặc khóa đĩa chống cắt cho xe máy. 2. Luôn khóa chốt cửa bên trong khi ở trong phòng và khóa móc ngoài khi đi ra ngoài dù chỉ vài phút. 3. Cất laptop và đồ trang sức vào tủ có khóa riêng. 4. Đề cao cảnh giác khi có người lạ vào hỏi tìm người trong dãy trọ.', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800', 'bảo vệ,tài sản,an ninh', 'PUBLISHED', 4, NOW(), NOW()),
(112, 1, 'CAMPUS', 'Top khu trọ sinh viên tiện lợi nhất quanh các trường đại học lớn', 'Khám phá các điểm nóng thuê trọ tại Cầu Giấy, Bách Khoa, Hòa Lạc, Thủ Đức và Bình Thạnh.', 'Mỗi khu vực đại học có đặc thù riêng: Khu Cầu Giấy sầm uất nhiều quán ăn nhưng giá cao; khu Bách Kinh Xây nhiều ngõ nhỏ giá mềm; khu Hòa Lạc thiên nhiên thoáng mát, phương tiện công cộng thuận tiện; làng ĐHQG Thủ Đức chi phí rẻ, ký túc xá hiện đại. Chọn đúng khu vực sẽ giúp bạn tiết kiệm hàng giờ di chuyển mỗi ngày.', 'https://images.unsplash.com/photo-1477959858617-67f30bc75b82?w=800', 'khu trọ,đại học,vị trí', 'PUBLISHED', 5, NOW(), NOW()),
(113, 1, 'LIFESTYLE', 'Mẹo trang trí phòng trọ nhỏ hẹp thành không gian sống chill', 'Tận dụng đèn led, tranh canvas, thảm trải sàn và kệ treo tường để F5 căn phòng tiết kiệm nhất.', 'Biến căn phòng trọ 15m2 thành không gian thư giãn cực chill: 1. Sơn tường màu trắng hoặc be giúp mở rộng thị giác. 2. Dùng kệ treo tường thay cho tủ đứng cồng kềnh. 3. Bố trí dây đèn đom đóm vàng ấm bên góc học tập. 4. Đặt 1-2 chậu cây nhỏ như kim ngân, lưỡi hổ lọc không khí. Bạn sẽ luôn muốn trở về phòng sau giờ học tập căng thẳng.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=800', 'decor,trang trí,phòng đẹp', 'PUBLISHED', 5, NOW(), NOW()),
(114, 1, 'TIPS', 'Cách xử lý ẩm mốc và mùi hôi phòng trọ mùa nồm ẩm', 'Giải pháp hút ẩm tự nhiên bằng vôi sống, bã cà phê và máy hút ẩm mini hiệu quả bất ngờ.', 'Mùa nồm ẩm miền Bắc là nỗi kinh hoàng cho quần áo và đồ điện tử: 1. Hạn chế mở toang cửa sổ khi độ ẩm ngoài trời trên 85%. 2. Đặt túi bã cà phê hoặc than hoạt tính ở các góc phòng để hút mùi. 3. Bật điều hòa chế độ Dry (hút ẩm) 30 phút mỗi ngày. 4. Lau sàn nhà bằng khăn khô thay vì khăn ướt.', 'https://images.unsplash.com/photo-1584820927498-cfe5211fd8bf?w=800', 'nồm ẩm,ẩm mốc,mẹo vặt', 'PUBLISHED', 4, NOW(), NOW()),
(115, 1, 'EXPERIENCE', 'Kinh nghiệm pass đồ cũ nhanh chóng và được giá trên UniHome', 'Cách chụp ảnh sản phẩm, viết mô tả trung thực và định giá thu hút người mua sinh viên.', 'Dọn phòng trọ thừa đồ không dùng? Pass đồ ngay cho sinh viên cùng trường: 1. Chụp ảnh sản phẩm dưới ánh sáng tự nhiên rõ nét mọi góc cạnh. 2. Mô tả rõ tình trạng thật, vết trầy xước (nếu có) để tạo niềm tin. 3. Định giá hợp lý bằng 40-60% giá mới tùy độ hao mòn. 4. Hỗ trợ ship gần hoặc bớt chút tiền xăng xe cho các bạn sinh viên nhiệt tình.', 'https://images.unsplash.com/photo-1518455027359-f3f8164ba6bd?w=800', 'pass đồ,thanh lý,tiết kiệm', 'PUBLISHED', 4, NOW(), NOW()),
(116, 1, 'HEALTH', 'Bảo vệ sức khỏe khi ở phòng trọ: Nước uống và không khí', 'Tầm quan trọng của bình lọc nước gia đình và cách giữ thông gió tự nhiên trong phòng kín.', 'Sức khỏe là vốn quý nhất: 1. Sử dụng bình nước lọc có thương hiệu rõ ràng, tránh bình nước đổi 10.000đ không rõ nguồn gốc. 2. Mở cửa sổ đón gió tươi ít nhất 15 phút mỗi sáng thức dậy. 3. Thường xuyên giặt giũ ga gối 2 tuần 1 lần để phòng tránh bệnh về da và đường hô hấp. 4. Giữ thói quen ăn chín uống sôi và rèn luyện thể thao hàng ngày.', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800', 'sức khỏe,nước sạch,không khí', 'PUBLISHED', 5, NOW(), NOW()),
(117, 1, 'LEGAL', 'Quy định pháp luật về giá bán lẻ điện cho sinh viên thuê nhà', 'Chủ nhà trọ thu tiền điện giá cao có vi phạm không? Mức giá chuẩn theo Bộ Công Thương.', 'Theo Thông tư số 25/2018/TT-BCT, người thuê nhà có hợp đồng từ 12 tháng trở lên được đăng ký định mức giá điện bậc thang như hộ gia đình. Trường hợp không kê khai được định mức, chủ trọ chỉ được phép thu theo giá bán lẻ điện sinh hoạt bậc 3 (khoảng 2.167đ/kWh chưa VAT) cộng chi phí hao hụt hợp lý. Hành vi thu 4.500đ - 5.000đ/kWh có thể bị xử phạt hành chính từ 7 đến 10 triệu đồng.', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800', 'giá điện,pháp luật,sinh viên', 'PUBLISHED', 6, NOW(), NOW()),
(118, 1, 'COMMUNITY', 'Tìm bạn cùng phòng lý tưởng bằng tính năng Matching UniHome', 'Ứng dụng thuật toán AI phân tích tương thích thói quen sinh hoạt, giờ giấc và ngân sách.', 'UniHome Matching giúp bạn tìm bạn ở ghép như ý: 1. Điền hồ sơ chi tiết về giờ giấc đi ngủ, mức độ sạch sẽ, giới tính và sở thích. 2. Thuật toán chấm điểm độ hòa hợp trên 10 tiêu chí quan trọng. 3. Trò chuyện trực tiếp trên UniHome Chat trước khi quyết định gặp mặt. 4. Không còn nỗi lo sốc thói quen sinh hoạt khi về ở chung.', 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800', 'matching,ở ghép,unihome', 'PUBLISHED', 4, NOW(), NOW()),
(119, 1, 'CAREER', 'Cân bằng giữa việc học tập và làm thêm khi ở trọ', 'Phương pháp quản lý thời gian Pomodoro và quản lý tài chính thông minh cho sinh viên tự lập.', 'Tự lập không chỉ là trả tiền phòng đúng hạn mà là làm chủ cuộc sống: 1. Sắp xếp lịch học và làm thêm không quá 20 giờ mỗi tuần để không ảnh hưởng điểm số. 2. Tạo lập quỹ dự phòng khẩn cấp ít nhất 2 tháng tiền nhà. 3. Học cách từ chối các buổi tiệc tùng tốn kém không cần thiết. 4. Dành thời gian nghỉ ngơi để tái tạo năng lượng học tập.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800', 'quản lý thời gian,làm thêm,tự lập', 'PUBLISHED', 5, NOW(), NOW()),
(120, 1, 'PETS', 'Kinh nghiệm nuôi thú cưng tại phòng trọ không gây phiền hà', 'Quy tắc vệ sinh khép kín, khử mùi và thương lượng với chủ nhà trọ trước khi đón cún mèo.', 'Nuôi thú cưng tại phòng trọ đòi hỏi trách nhiệm cao: 1. Phải được sự đồng ý bằng văn bản của chủ nhà trong hợp đồng. 2. Tiêm phòng dại và tẩy giun đầy đủ định kỳ. 3. Dùng cát vệ sinh chuyên dụng và dọn dẹp hàng ngày, không để phát sinh mùi hôi sang phòng bên cạnh. 4. Huấn luyện thú cưng không sủa hoặc cào cửa gây ồn ào vào ban đêm.', 'https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800', 'thú cưng,nuôi mèo,phòng trọ', 'PUBLISHED', 5, NOW(), NOW()),
(121, 1, 'TIPS', 'Bí kíp thương lượng giá thuê phòng trọ thành công', 'Cách đàm phán giảm giá phòng, miễn phí gửi xe hoặc đóng cọc linh hoạt cho sinh viên.', 'Chủ nhà trọ hoàn toàn có thể giảm giá nếu bạn biết cách: 1. Cam kết ký hợp đồng dài hạn từ 1 đến 2 năm. 2. Thanh toán tiền trọ đúng hạn vào đầu tháng. 3. Trình bày hoàn cảnh sinh viên chăm ngoan, giữ gìn nhà cửa sạch sẽ cẩn thận. 4. Đề xuất giảm tiền gửi xe hoặc tiền dịch vụ nếu không giảm được trực tiếp tiền phòng.', 'https://images.unsplash.com/photo-1556742049-0a67e557224d?w=800', 'thương lượng,đàm phán,giá phòng', 'PUBLISHED', 4, NOW(), NOW())
INSERT INTO question (id, user_id, title, content, category, status, created_at) VALUES
(100, 4, 'Chủ trọ thu tiền điện 4.500đ/kWh có vi phạm quy định nhà nước không?', 'Chỗ mình đang ở trọ chủ nhà thu tiền điện 4.500đ/kWh, nước 35.000đ/khối. Cho mình hỏi mức này có đúng quy định không và sinh viên có thể kiến nghị như thế nào?', 'CHI_PHI', 'OPEN', NOW()),
(101, 5, 'Ở ghép có cần ký hợp đồng phụ giữa các bạn cùng phòng không?', 'Tụi mình dự định thuê chung căn chung cư mini 2 phòng ngủ 4 người. Có nên làm hợp đồng thỏa thuận nội bộ giữa các bạn để tránh trường hợp một bạn đột ngột dọn đi không?', 'O_GHEP', 'OPEN', NOW()),
(102, 6, 'Khu Hòa Lạc gần ĐHQG và FPT có phòng trọ nào cho nuôi mèo không?', 'Mình là sinh viên năm nhất FPT, mình có nuôi 1 bé mèo ta đã tiêm phòng và biết đi vệ sinh đúng chỗ. Khu vực Tân Xã hay Hạ Bằng có phòng nào chủ nhà thoải mái vụ này không?', 'TIM_PHONG', 'OPEN', NOW()),
(103, 15, 'Chủ trọ không chịu trả lại tiền cọc khi hết hợp đồng thì giải quyết sao?', 'Mình hết hạn hợp đồng báo trước 30 ngày đúng quy định, bàn giao phòng sạch sẽ nhưng chủ trọ cứ viện cớ trì hoãn không trả 3 triệu tiền cọc. Mình phải làm gì?', 'PHAP_LY', 'OPEN', NOW()),
(104, 16, 'Làm thế nào để đăng ký tạm trú online qua VNeID khi chủ trọ không hỗ trợ?', 'Chủ nhà trọ của mình bảo bận không đi làm tạm trú được, bảo mình tự làm. Cho mình hỏi trên app VNeID cần những giấy tờ gì để tự khai báo được?', 'THU_TUC', 'OPEN', NOW()),
(105, 17, 'Nên chọn phòng trọ có gác lửng hay phòng đơn cùng diện tích?', 'Mình đang phân vân giữa phòng 22m2 có gác và phòng 25m2 sàn phẳng cùng tầm giá 3.5 triệu ở Cầu Giấy. Bạn nào đã ở cả hai loại rồi cho mình xin lời khuyên với.', 'KINH_NGHIEM', 'OPEN', NOW()),
(106, 18, 'Phòng trọ mùa hè bị nắng chiếu thẳng vào tường thì làm mát cách nào?', 'Phòng mình hướng Tây buổi chiều như lò bát quái, bật điều hòa mãi không mát. Có mẹo nào chống nóng cách nhiệt giá sinh viên không mọi người?', 'ME_VAT', 'OPEN', NOW()),
(107, 19, 'Bị mất trộm xe máy trong nhà trọ thì chủ trọ có phải bồi thường không?', 'Khu trọ mình có camera và cổng vân tay, nhưng hôm qua kẻ gian cạy cổng lấy mất xe máy của mình. Chủ trọ bảo không có trách nhiệm trông xe, vậy có đúng luật không?', 'PHAP_LY', 'OPEN', NOW()),
(108, 20, 'Kinh nghiệm đi chợ nấu ăn cho 2 người ở ghép tiết kiệm nhất?', 'Tụi mình muốn tự nấu ăn để đảm bảo vệ sinh. Xin kinh nghiệm lên thực đơn và chi phí ăn uống trung bình mỗi tháng cho 2 người ở Hà Nội.', 'DOI_SONG', 'OPEN', NOW()),
(109, 21, 'Lắp mạng Internet riêng trong phòng trọ hay dùng chung mạng tòa nhà?', 'Mạng chung của xóm trọ buổi tối xem video giật lag quá không học online được. Mình có nên tự đăng ký gói mạng riêng không và xin phép chủ trọ thế nào?', 'TIEN_ICH', 'OPEN', NOW()),
(110, 68, 'Chủ trọ tăng giá phòng đột ngột giữa chừng thì phải làm sao?', 'Hợp đồng mình ký 1 năm mới ở được 4 tháng thì chủ trọ thông báo tháng sau tăng thêm 500k tiền phòng do trượt giá. Chủ trọ làm vậy có đúng không?', 'PHAP_LY', 'OPEN', NOW()),
(111, 69, 'Có nên thuê phòng trọ chung chủ không? Ưu và nhược điểm là gì?', 'Mình là nữ năm nhất mới lên Hà Nội, bố mẹ muốn mình ở chung chủ cho an toàn nhưng bạn bè bảo gò bó. Xin ý kiến thực tế của các anh chị đi trước.', 'KINH_NGHIEM', 'OPEN', NOW()),
(112, 70, 'Cách khử mùi hôi cống thoát nước nhà vệ sinh phòng trọ?', 'Nhà vệ sinh phòng mình cứ mỗi lần trở trời là bốc mùi cống rất khó chịu dù mình cọ rửa thường xuyên. Có cách nào xử lý dứt điểm không?', 'ME_VAT', 'OPEN', NOW()),
(113, 71, 'Lỡ làm hỏng điều hòa của phòng trọ thì bồi thường bao nhiêu là hợp lý?', 'Hôm qua cục lạnh điều hòa phòng mình kêu to rồi không mát, thợ đến bảo hỏng block. Chủ nhà bắt mình đền toàn bộ máy mới, mình có phải đền không?', 'TRANH_CHAP', 'OPEN', NOW()),
(114, 72, 'Kinh nghiệm tìm bạn ở ghép trên UniHome để không bị xích mích?', 'Mình muốn tìm 1 bạn nữ ở ghép căn hộ 2 phòng ngủ khu Đống Đa. Khi phỏng vấn bạn cùng phòng nên hỏi những câu gì để biết có hợp tính không?', 'O_GHEP', 'OPEN', NOW()),
(115, 80, 'Thủ tục chuyển nhượng phòng trọ (pass phòng) cho người khác thế nào?', 'Mình chuyển trường nên muốn pass lại phòng trọ còn 6 tháng hợp đồng. Cần làm những thủ tục gì với chủ nhà và người mới để lấy lại cọc an toàn?', 'THU_TUC', 'OPEN', NOW()),
(116, 81, 'Sinh viên thuê trọ có phải đóng thuế thu nhập hay phí an ninh trật tự không?', 'Đầu tháng chủ trọ thu thêm 50k phí an ninh trật tự tổ dân phố và 100k tiền rác. Mức thu này có hóa đơn chứng từ gì không mọi người?', 'CHI_PHI', 'OPEN', NOW()),
(117, 82, 'Nên dùng bếp từ hay bếp ga mini khi ở phòng trọ?', 'Nhiều người khuyên dùng bếp từ cho an toàn chống cháy nổ, nhưng có người bảo bếp ga nấu đồ xào ngon hơn. Xin ý kiến so sánh chi phí tiền điện với tiền bình ga.', 'TIEN_ICH', 'OPEN', NOW()),
(118, 83, 'Khu vực nào quanh Bách Khoa - Xây Dựng thuê trọ yên tĩnh, an ninh tốt?', 'Em cần tìm phòng bán kính 2km quanh ĐH Bách Khoa, yêu cầu yên tĩnh để tập trung học tập, ngõ không quá sâu. Nhờ các anh chị gợi ý các tuyến phố phù hợp.', 'TIM_PHONG', 'OPEN', NOW()),
(119, 84, 'Cách kiểm tra phòng trọ có bị ngập nước vào mùa mưa bão?', 'Mùa mưa bão sắp tới, em sợ thuê phải phòng trọ trũng thấp bị ngập nước vào nhà. Đi xem phòng vào mùa khô thì làm sao biết khu đó có ngập không?', 'KINH_NGHIEM', 'OPEN', NOW()),
(120, 85, 'Bị bạn cùng phòng trộm đồ và bỏ trốn thì xử lý thế nào?', 'Bạn ở ghép cùng mình vừa dọn đồ đi mất kèm theo chiếc laptop của mình. Mình chỉ có số điện thoại và ảnh CCCD của bạn ấy thì báo công an ở đâu?', 'AN_NINH', 'OPEN', NOW()),
(121, 86, 'Chủ trọ tự ý vào phòng khi người thuê vắng mặt có phạm luật không?', 'Hôm qua mình đi học về thấy đồ đạc bị xê dịch, hỏi thì chủ trọ bảo vào kiểm tra đường ống nước. Chủ trọ tự tiện mở cửa phòng như vậy có được phép không?', 'PHAP_LY', 'OPEN', NOW()),
(122, 87, 'Cách chia tiền điện khi 1 người dùng máy tính bàn 1 người dùng laptop?', 'Phòng mình ở ghép 2 người, bạn kia dùng máy tính bàn cắm game 24/24 còn mình chỉ dùng laptop học bài. Chia đôi tiền điện thì mình thấy hơi thiệt, nên nói sao?', 'O_GHEP', 'OPEN', NOW()),
(123, 88, 'Cần chuẩn bị những đồ đạc gì tối thiểu cho phòng trọ mới thuê?', 'Em lần đầu ra ở riêng, phòng trọ mới chỉ có sẵn giường và nóng lạnh. Nhờ mọi người tư vấn danh sách đồ dùng thiết yếu cần mua sắm với ngân sách 3 triệu.', 'DOI_SONG', 'OPEN', NOW()),
(124, 89, 'Có nên ký hợp đồng thuê trọ 2 năm để được giảm giá phòng?', 'Chủ nhà bảo nếu em ký hợp đồng 2 năm thì giảm cho 300k/tháng. Em đang phân vân không biết có nên ký dài vậy không, nhỡ sau này muốn chuyển thì sao?', 'HOP_DONG', 'OPEN', NOW()),
(125, 90, 'Thuê trọ gần chợ có tiện lợi hay ồn ào phức tạp?', 'Em thấy có phòng ngay cạnh chợ Nghĩa Tân giá khá tốt. Mọi người cho em hỏi ở gần chợ thì có những phiền toái gì cần lường trước không?', 'TIM_PHONG', 'OPEN', NOW()),
(126, 91, 'Đồ đạc bị ẩm mốc trong phòng trọ kín thì khắc phục thế nào?', 'Phòng trọ em không có cửa sổ nên quần áo treo trong tủ hay bị mốc trắng và mùi khó chịu. Mọi người có cách nào giữ phòng luôn khô ráo không?', 'ME_VAT', 'OPEN', NOW()),
(127, 92, 'Làm gì khi hàng xóm phòng bên cạnh thường xuyên nhậu nhẹt hát karaoke ồn ào?', 'Dãy trọ em có phòng bên cạnh tối nào cũng tụ tập bạn bè uống bia hát hò đến 1h sáng. Em đã nhắc nhở nhưng không đỡ, giờ nên báo chủ trọ hay công an?', 'VAN_HOA', 'OPEN', NOW()),
(128, 93, 'Kinh nghiệm thuê phòng trọ mùa nhập học không bị chặt chém?', 'Tháng 9 tân sinh viên lên đông, giá phòng trọ thường bị đẩy lên cao. Có kinh nghiệm nào tìm được phòng giá gốc hợp lý thời điểm này không ạ?', 'KINH_NGHIEM', 'OPEN', NOW()),
(129, 94, 'Phòng trọ có cửa thoát hiểm khóa chặt thì có được yêu cầu mở không?', 'Tòa chung cư mini em đang thuê có cửa thoát hiểm tầng 1 nhưng chủ nhà luôn khóa xích lại vì sợ trộm. Em rất lo khi có cháy, trường hợp này phản ánh ở đâu?', 'AN_TOAN', 'OPEN', NOW()),
(130, 95, 'Cách tính tiền nước sinh hoạt theo đầu người hay theo đồng hồ khối?', 'Chủ trọ tính 100k/người/tháng tiền nước thì đắt hay rẻ so với tính 30k/khối qua đồng hồ riêng vậy mọi người?', 'CHI_PHI', 'OPEN', NOW()),
(131, 96, 'Ký hợp đồng thuê trọ viết tay có giá trị pháp lý không?', 'Chủ nhà trọ là người lớn tuổi chỉ viết giấy tay cho em chứ không in hợp đồng mẫu. Hợp đồng viết tay có chữ ký hai bên thì có được pháp luật bảo vệ không?', 'PHAP_LY', 'OPEN', NOW())
INSERT INTO answer (id, question_id, user_id, content, status, created_at) VALUES
(100, 100, 1, 'Theo Thông tư của Bộ Công Thương, chủ nhà trọ thu 4.500đ/kWh là cao hơn nhiều so với quy định giá bán lẻ điện sinh hoạt. Bạn có thể nhẹ nhàng trao đổi lại với chủ nhà hoặc cùng các bạn trong xóm trọ làm đơn kiến nghị lên UBND phường.', 'APPROVED', NOW()),
(101, 100, 2, 'Thường các chủ trọ tính 4.000 - 4.500đ để bù vào điện thắp sáng chung, máy bơm nước và điện thang máy. Nhưng nếu không có thang máy mà thu giá đó là quá đắt bạn nhé.', 'APPROVED', NOW()),
(102, 101, 4, 'Rất nên bạn nhé! Tụi mình đã lập biên bản thỏa thuận nội bộ ghi rõ: Ai chuyển đi trước thời hạn phải tự tìm người thay thế hoặc chịu mất tiền cọc phần của mình. Nhờ vậy tụi mình ở với nhau 3 năm rất vui vẻ.', 'APPROVED', NOW()),
(103, 101, 5, 'Nên có quy định rõ ràng về giờ giấc, dọn vệ sinh luân phiên và chi phí phát sinh. Văn bản giấy trắng mực đen giúp mọi người có trách nhiệm hơn.', 'APPROVED', NOW()),
(104, 102, 9, 'Chào bạn, khu Tân Xã gần hồ có nhiều homestay và nhà trọ riêng biệt rất thoáng cho nuôi thú cưng. Bạn có thể tìm các phòng có ban công riêng trên UniHome và nhắn tin hỏi chủ trước nhé.', 'APPROVED', NOW()),
(105, 102, 18, 'Mình đang ở phòng trọ ở Thạch Hòa cũng nuôi 1 bé mèo, chủ nhà chỉ yêu cầu dùng cát vệ sinh và không để mèo cào rách ghế nệm thôi. Khu này các bác chủ trọ dễ tính lắm.', 'APPROVED', NOW()),
(106, 103, 1, 'Nếu bạn có đầy đủ bằng chứng đã báo trước 30 ngày (tin nhắn, văn bản) và biên bản bàn giao phòng nguyên vẹn, bạn có thể gửi đơn phản ánh lên công an phường sở tại nhờ can thiệp.', 'APPROVED', NOW()),
(107, 103, 8, 'Kinh nghiệm của mình là rủ thêm bạn bè đến nói chuyện lịch sự nhưng cương quyết với chủ nhà, viện dẫn các điều khoản hợp đồng. Đa số chủ nhà sẽ trả lại cọc để tránh rắc rối.', 'APPROVED', NOW()),
(108, 104, 1, 'Bạn chỉ cần có CCCD gắn chip kích hoạt VNeID mức 2, chụp ảnh hợp đồng thuê nhà rõ nét và điền đúng mã định danh của chủ trọ là nộp hồ sơ online được nhé, không cần chủ nhà đi cùng.', 'APPROVED', NOW()),
(109, 104, 20, 'Mình vừa tự làm xong tuần trước, mất khoảng 3 ngày là công an phường duyệt thành công trên app VNeID, rất tiện lợi.', 'APPROVED', NOW()),
(110, 105, 17, 'Phòng có gác lửng thì tách biệt được chỗ ngủ và chỗ nấu ăn, nhưng mùa hè trên gác sẽ nóng hơn sàn khoảng 2-3 độ. Nếu phòng có điều hòa tốt thì nên chọn phòng gác lửng nhé.', 'APPROVED', NOW()),
(111, 105, 21, 'Mình vote phòng sàn phẳng 25m2, đi lại lau chùi tiện hơn nhiều, không phải leo cầu thang mỗi lần nửa đêm đi vệ sinh.', 'APPROVED', NOW()),
(112, 106, 4, 'Bạn mua tấm xốp tráng bạc cách nhiệt (khoảng 35k/mét) dán lên bức tường hướng Tây, kết hợp kéo rèm cửa màu sáng sẽ giảm được 4-5 độ nhiệt độ trong phòng đấy.', 'APPROVED', NOW()),
(113, 106, 68, 'Đặt thêm 1 chậu nước to trước quạt gió hoặc mua quạt hơi nước mini để phòng dịu mát hơn vào giờ cao điểm chiều tối nhé.', 'APPROVED', NOW()),
(114, 107, 1, 'Nếu trong hợp đồng hoặc nội quy xóm trọ có thu phí gửi xe hàng tháng thì bên cho thuê có trách nhiệm trông giữ và phải bồi thường theo Bộ luật Dân sự.', 'APPROVED', NOW()),
(115, 108, 15, 'Tụi mình mỗi tuần đi chợ đầu mối 1 lần vào sáng Chủ nhật hết khoảng 350k, mua thịt về chia túi zip cấp đông. Trung bình mỗi bạn hết tầm 1.2 triệu tiền ăn/tháng mà cơm canh đề huề.', 'APPROVED', NOW()),
(116, 108, 16, 'Nấu ăn chung nhớ sắm nồi cơm điện đa năng và hộp thủy tinh để trữ thức ăn, vừa sạch sẽ vừa tiết kiệm thời gian nấu nướng giữa mùa thi cử.', 'APPROVED', NOW()),
(117, 109, 3, 'Nếu công việc hoặc học tập cần mạng ổn định, bạn nên rủ 2-3 phòng bên cạnh cùng kéo chung 1 đường truyền FPT hoặc Viettel tốc độ cao rồi chia tiền, mỗi phòng tầm 70k mà mạng nhanh gấp 5 lần mạng xóm.', 'APPROVED', NOW()),
(118, 110, 1, 'Chủ trọ làm vậy là sai luật bạn nhé. Trong thời hạn hợp đồng còn hiệu lực, mọi thay đổi về giá thuê phải được cả hai bên đồng thuận bằng văn bản. Bạn hoàn toàn có quyền từ chối mức tăng giá này.', 'APPROVED', NOW()),
(119, 111, 15, 'Ở chung chủ thì an ninh tốt, ít khi xảy ra trộm cắp, nhưng bù lại giờ giấc sẽ bị giới hạn (thường đóng cửa lúc 23h) và ít khi được dẫn bạn bè về chơi thoải mái.', 'APPROVED', NOW()),
(120, 111, 70, 'Tân sinh viên năm nhất chưa quen cuộc sống tự lập ở chung chủ 1 năm đầu cũng tốt, sau quen đường xá và bạn bè rồi chuyển ra ở riêng tự do hơn.', 'APPROVED', NOW()),
(121, 112, 14, 'Bạn mua nắp cống silicon ngăn mùi (loại có van đóng mở tự động giá tầm 25k trên Shopee) gắn vào miệng cống là hết sạch mùi hôi cống ngay lập tức.', 'APPROVED', NOW()),
(122, 113, 14, 'Block máy lạnh hỏng do thời gian sử dụng lâu năm thuộc hao mòn tự nhiên, trách nhiệm sửa chữa hoặc thay mới thuộc về chủ nhà trọ, trừ khi bạn cố ý đập phá.', 'APPROVED', NOW()),
(123, 114, 4, 'Bạn hãy dùng tính năng Matching trên UniHome để xem điểm tương thích thói quen sinh hoạt trước. Khi gặp nói chuyện, nhớ hỏi rõ: Bạn ngủ lúc mấy giờ, có hút thuốc không, cuối tuần có hay về quê không.', 'APPROVED', NOW()),
(124, 115, 6, 'Bạn tìm được khách mới xong thì hẹn cả khách mới và chủ nhà ra phòng đối chiếu hiện trạng, chủ nhà trả cọc cho bạn và khách mới ký hợp đồng mới nộp cọc lại cho chủ là chuẩn nhất.', 'APPROVED', NOW()),
(125, 116, 2, 'Tiền rác 30-50k là bình thường vì công ty môi trường đô thị đi thu hàng tháng. Tiền an ninh trật tự thường là tự nguyện đóng góp cho tổ dân phố, chủ trọ nên thông báo rõ ràng.', 'APPROVED', NOW()),
(126, 117, 17, 'Bếp từ an toàn hơn hẳn bạn ơi, phòng trọ kín dùng bếp ga mini rất dễ rò rỉ khí ga hoặc nổ bình ga mini cũ nát, tiền điện nấu bếp từ mỗi tháng chỉ khoảng 60k - 80k thôi.', 'APPROVED', NOW()),
(127, 118, 10, 'Khu vực ngõ 102 Trường Chinh hoặc ngõ 46 Phạm Ngọc Thạch cách Bách Khoa tầm 1km, là khu dân cư cán bộ rất yên tĩnh, đường sá rộng rãi an ninh cực tốt.', 'APPROVED', NOW()),
(128, 119, 87, 'Bạn nhìn chân tường các nhà xung quanh, nếu có vết rêu mốc hoặc vệt ố vàng cách mặt đất 30-50cm thì chắc chắn khu đó mùa mưa bị ngập lụt.', 'APPROVED', NOW()),
(129, 120, 8, 'Bạn mang ngay bản sao hợp đồng thuê phòng, ảnh CCCD của bạn đó ra công an phường nơi bạn đăng ký tạm trú để trình báo tội trộm cắp tài sản. Giá trị trên 2 triệu là khởi tố hình sự được rồi.', 'APPROVED', NOW()),
(130, 121, 1, 'Hành vi tự ý vào phòng của người thuê khi chưa được đồng ý là xâm phạm chỗ ở bất hợp pháp theo Điều 158 Bộ luật Hình sự. Bạn nên nhắc nhở chủ nhà và thay ổ khóa riêng nếu cần.', 'APPROVED', NOW()),
(131, 122, 5, 'Bạn có thể mua 1 chiếc công tơ điện mini cắm ổ cắm (giá tầm 120k) để đo riêng lượng điện cây máy tính dùng trong 1 tháng, số điện dôi ra thì bạn kia tự chi trả, rất công bằng.', 'APPROVED', NOW()),
(132, 123, 16, 'Đồ thiết yếu: 1. Nồi cơm điện + chảo chống dính. 2. Quạt cây. 3. Đệm gấp + ga gối. 4. Bộ móc áo + giỏ đựng đồ. 5. Xô chậu + cây lau nhà. Mua đồ cũ trên UniHome Pass Đồ chỉ tốn tầm 1.5 triệu là đủ hết.', 'APPROVED', NOW()),
(133, 124, 2, 'Không nên ký 2 năm bạn nhé. Thời sinh viên nhiều biến động (đổi bạn ở cùng, chuyển cơ sở học, đi thực tập...). Tối đa chỉ nên ký 1 năm hoặc 6 tháng.', 'APPROVED', NOW()),
(134, 125, 4, 'Ở gần chợ mua đồ ăn rất tiện và rẻ, nhưng nhược điểm là 5h sáng tiểu thương đã dọn hàng bấm còi ồn ào và chiều tối có mùi rác thải chợ.', 'APPROVED', NOW()),
(135, 126, 72, 'Bạn mua 1 hộp hút ẩm than hoạt tính đặt trong tủ quần áo và treo thêm túi thơm long não, quần áo sẽ luôn khô ráo không sợ ẩm mốc.', 'APPROVED', NOW()),
(136, 127, 8, 'Bạn quay video làm bằng chứng và báo chủ nhà trước. Nếu chủ nhà không xử lý thì gọi trực tiếp công an phường đến nhắc nhở lỗi gây mất trật tự công cộng sau 22h.', 'APPROVED', NOW()),
(137, 128, 70, 'Nên tìm phòng trước ngày nhập học 2-3 tuần, hoặc tìm qua nền tảng UniHome để xem tin chính chủ đã xác thực, không qua môi giới chặt chém.', 'APPROVED', NOW()),
(138, 129, 1, 'Khóa cửa thoát hiểm là vi phạm nghiêm trọng quy định an toàn PCCC. Bạn cần yêu cầu chủ nhà lắp thanh thoát hiểm một chiều (bên trong ấn mở được, bên ngoài không vào được) ngay lập tức.', 'APPROVED', NOW()),
(139, 130, 9, 'Tính 100k/người là tương đối hợp lý cho sinh viên dùng thoải mái giặt giũ nấu ăn. Nếu tính 30k/khối thì trung bình 1 người dùng 2-3 khối/tháng cũng tương đương 60k - 90k.', 'APPROVED', NOW()),
(140, 131, 1, 'Hợp đồng viết tay có đầy đủ thông tin hai bên, thỏa thuận rõ ràng và chữ ký thì vẫn có hiệu lực pháp lý theo Bộ luật Dân sự bạn nhé.', 'APPROVED', NOW()),
(141, 100, 10, 'Mình ở khu Bách Khoa chủ nhà cũng chỉ thu 3.800đ/kWh thôi, 4.500đ là hơi chát rồi bạn ơi.', 'APPROVED', NOW()),
(142, 101, 20, 'Tụi mình làm bảng phân công việc nhà dán ngay cửa tủ lạnh: Thứ 2-4 bạn A nấu cơm bạn B rửa bát, thứ 3-5 ngược lại, rất khoa học.', 'APPROVED', NOW()),
(143, 103, 11, 'Lần sau trước khi dọn đi bạn nhớ quay clip toàn bộ căn phòng lúc sạch sẽ để làm bằng chứng nhé.', 'APPROVED', NOW()),
(144, 105, 80, 'Gác lửng để làm phòng ngủ riêng tư rất thích, nhất là khi có bạn bè đến phòng chơi chỉ ngồi ở tầng dưới.', 'APPROVED', NOW()),
(145, 106, 91, 'Dán decal cách nhiệt lên cửa kính nữa nhé bạn, ánh nắng đỡ chiếu chói chang vào phòng.', 'APPROVED', NOW()),
(146, 108, 69, 'Mua sắm gia vị nên mua chai to dùng chung cho rẻ, đừng mua từng gói nhỏ rất tốn kém.', 'APPROVED', NOW()),
(147, 111, 85, 'Nếu sợ gò bó thì tìm nhà trọ không chung chủ có camera và bảo vệ là an tâm nhất.', 'APPROVED', NOW()),
(148, 114, 82, 'Thuật toán Matching của UniHome chuẩn lắm bạn ơi, mình tìm được bạn cùng phòng ở đến nay 2 năm rồi cực kỳ hợp cạ.', 'APPROVED', NOW()),
(149, 117, 86, 'Vote bếp từ 100%, vừa sạch sẽ lau mặt kính dễ dàng vừa không sợ cháy nổ.', 'APPROVED', NOW()),
(150, 118, 93, 'Đường Tạ Quang Bửu nhiều ngõ yên tĩnh lắm, sinh viên Bách Khoa ở đây nhiều.', 'APPROVED', NOW()),
(151, 123, 94, 'Nhớ sắm thêm 1 ấm siêu tốc để đun nước uống và nấu mì khuya nhé bạn.', 'APPROVED', NOW()),
(152, 126, 95, 'Mùa nồm bật điều hòa chế độ Dry 30 phút là phòng khô cong.', 'APPROVED', NOW()),
(153, 129, 96, 'An toàn là trên hết, nếu chủ nhà không mở cửa thoát hiểm thì nên tìm phòng khác chuyển đi sớm.', 'APPROVED', NOW()),
(154, 130, 97, 'Nếu phòng có máy giặt riêng thì dùng đồng hồ khối sẽ công bằng hơn.', 'APPROVED', NOW())
INSERT INTO conversation (id, user1_id, user2_id, context_type, context_id, context_title, context_image, context_price, created_at, updated_at) VALUES
(20, 2, 4, 'ROOM', 50, 'Căn hộ Studio Full Đồ Cầu Giấy', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800', '4.500.000đ/tháng', NOW(), NOW()),
