(26, 9, 18, 'ROOM', 51, 'Phòng Trọ Khép Kín Hòa Lạc', 'https://images.unsplash.com/photo-1598928506311-c55ded91a20c?w=800', '2.300.000đ/tháng', NOW(), NOW()),
(27, 13, 19, 'SERVICE', 31, 'Dịch vụ giặt sấy sinh viên', 'https://images.unsplash.com/photo-1517677208171-0bc6725a3e60?w=600', '25.000đ/kg', NOW(), NOW()),
